  "output": {
    "research_concepts": [
      "DRIVE play type",
      "PNR play type",
      "teammate interaction",
      "possession sequencing",
      "points per possession (PPP)",
      "play-type labeling reliability",
      "confounding by game context"
    ],
    "methodological_questions": [
      "operational definition of preceding action",
      "attribution of points in multi-action possessions",
      "reliability of play-by-play play-type labels",
      "control for confounding variables in sequence analyses",
      "sample size for rare action sequences",
      "selection bias in possession flow"
    ],
    "historical_evidence": [
      {
        "id": "FAM:SF-APPA-058",
        "status_as_recorded": "rejected",
        "finding": "Only 2/30 stars had stable top sequential suppressors across seasons. One specific teammate sequence, Giannis Antetokounmpo → Damian Lillard DRIVE→PNR, showed a negative premium of -0.263 (n=31)."
      },
      {
        "id": "FAM:SF-CHT-025",
        "status_as_recorded": "artifact",
        "finding": "DRIVE play-type labels exhibit foul leakage: DRIVE PPP is 12pp below the foul benchmark, indicating systematic under-counting of foul-ending drives (FOUL_LEAK). OTHER possessions are inflated by foul-ending inclusion. Only 0.7% of possessions map via initiation_type."
