      "p_testable": 0.3,
      "blocking_constraints": [
        {
          "code": "MEASURE_RELIABILITY",
          "text": "DRIVE labels are known to exhibit foul leakage and under-represent foul-ending drives (SF-CHT-025), so any exposure variable based on these labels is substantially misclassified."
        },
